import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Mfumo wa Kuzuia na Kudhibiti Paradoksi ya Wakati","description":"","frontmatter":{},"headers":[],"relativePath":"sw/89-时间悖论防控机制.md","filePath":"sw/89-时间悖论防控机制.md","lastUpdated":1789183869000}'),t={name:"sw/89-时间悖论防控机制.md"};function o(e,a,w,m,h,s){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="mfumo-wa-kuzuia-na-kudhibiti-paradoksi-ya-wakati" tabindex="-1">Mfumo wa Kuzuia na Kudhibiti Paradoksi ya Wakati <a class="header-anchor" href="#mfumo-wa-kuzuia-na-kudhibiti-paradoksi-ya-wakati" aria-label="Permalink to &quot;Mfumo wa Kuzuia na Kudhibiti Paradoksi ya Wakati&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>89</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Paradoksi ya wakati, kuzuia paradoksi, urekebishaji wa sababu-na-matokeo, uthabiti wa mstari wa wakati, uainishaji wa paradoksi</td></tr></tbody></table><h2 id="_1-ufafanuzi-na-hatari-za-paradoksi-ya-wakati" tabindex="-1">1. Ufafanuzi na Hatari za Paradoksi ya Wakati <a class="header-anchor" href="#_1-ufafanuzi-na-hatari-za-paradoksi-ya-wakati" aria-label="Permalink to &quot;1. Ufafanuzi na Hatari za Paradoksi ya Wakati&quot;">​</a></h2><p>Paradoksi ya wakati inahusu hali ambayo, katika operesheni ya kurudi nyuma kwa wakati, tabia ya kuingilia sababu-na-matokeo inasababisha utata wa kimantiki. Paradoksi ya wakati ni matokeo yenye hatari zaidi katika operesheni za kurudi nyuma kwa wakati, na mara moja inapotokea na isitikelewe kwa wakati, inaweza kusababisha mgawanyiko wa mstari wa wakati, kuanguka kwa mnyororo wa sababu-na-matokeo, na hata mtetemo wa sheria wa kiwango cha ulimwengu. Kwa hivyo, mfumo wa kuzuia na kudhibiti paradoksi ya wakati ni sehemu ya msingi na muhimu zaidi katika mfumo wote wa usalama wa kurudi nyuma kwa wakati.</p><p>Kiini cha paradoksi ya wakati ni &quot;kushindwa kwa kufungwa kwa sababu-na-matokeo&quot;. Katika mtiririko wa kawaida wa wakati, kila tukio lina sababu yake ya awali na matokeo yake ya baadaye, na mnyororo wa sababu-na-matokeo unaonyesha muundo wa mstari unaoendelea. Operesheni ya kurudi nyuma kwa wakati inaleta uingizwaji wa kutoka kwa wakati ujao katika kipindi cha wakati cha zamani, na kama tabia ya uingizwaji huu inabadilisha masharti ya sababu-na-matokeo yaliyosababisha uwepo wake mwenyewe, basi &quot;kutengana kwa mzunguko wa sababu-na-matokeo uliofungwa&quot; kunatokea — yaani utata wa kimantiki wa kwamba ikiwa A inatokea, basi A haitatokea. Utata huu katika kiwango cha sheria huonyeshwa kama mgongano mkali wa nishati ya sababu-na-matokeo, na ikiwa nishati ya mgongano haiiwezi kufyonzwa na mtandao wa sheria, inajipaza katika umbo la paradoksi ya wakati.</p><p>Kiwewe cha hatari ya paradoksi ya wakati kinategemea ukubwa wa paradoksi na nafasi inayotokea. Paradoksi za ukubwa mdogo (kama vile kubadilisha uchaguzi wa kila siku wa mtu wa kawaida) zinaweza kusababisha tu mabadiliko ya sababu-na-matokeo ya eneo, na mtandao wa sheria unaweza kufyonza na kurekebisha mwenyewe; paradoksi za ukubwa wa kati (kama vile kubadilisha hatima ya mtu muhimu wa kihistoria) zinaweza kusababisha matawi ya mstari wa wakati, na kuunda mstari wa wakati wa sambamba; paradoksi za ukubwa mkubwa (kama vile kubadilisha mwelekeo wa tukio la kihistoria la kiwango cha ustaarabu) zinaweza kusababisha kuanguka kwa mnyororo wa sababu-na-matokeo, na kusababisha muundo wa sheria wa mstari wote wa wakati kuvunjika. Lengo la mfumo wa kuzuia na kudhibiti paradoksi ya wakati wa Hengyuanzhou ni kuua paradoksi katika hali ya mbegu, na kuhakikisha kuwa hakuna operesheni ya kurudi nyuma kwa wakati inayosababisha paradoksi za ukubwa wa kati au zaidi.</p><h2 id="_2-uainishaji-wa-paradoksi-za-wakati" tabindex="-1">2. Uainishaji wa Paradoksi za Wakati <a class="header-anchor" href="#_2-uainishaji-wa-paradoksi-za-wakati" aria-label="Permalink to &quot;2. Uainishaji wa Paradoksi za Wakati&quot;">​</a></h2><p>Kulingana na mchakato wa kuundwa na umbo wa kuonyeshwa wa paradoksi, paradoksi za wakati zimegawanywa katika aina nne kuu zifuatazo:</p><table tabindex="0"><thead><tr><th>Aina ya Paradoksi</th><th>Mchakato wa Kuundwa</th><th>Kisa cha Kawaida</th><th>Kiwango cha Hatari</th></tr></thead><tbody><tr><td>Paradoksi ya Kuua Babu</td><td>Tabia ya mtu anayerudi nyuma inasababisha masharti ya sababu-na-matokeo ya uwepo wake mwenyewe kufutwa</td><td>Mtu anayerudi nyuma anaua babu yake mwenyewe katika zamani, na kusababisha yeye hujawahi kuzaliwa</td><td>Juu sana (nyekundu)</td></tr><tr><td>Paradoksi ya Taarifa</td><td>Taarifa inatolewa kutoka kwa wakati ujao hadi zamani, inapokelewa na kukuza na watu wa zamani, na mwishowe inakuwa chanzo cha taarifa za wakati ujao, na kuunda mzunguko wa taarifa usio na chanzo</td><td>Mwanasayansi wa wakati ujao anatuma nadharia moja hadi zamani, mwanasayansi wa zamani anachapisha nadharia hiyo, na mwanasayansi wa wakati ujao alijifunza nadharia hiyo kutoka kwa nyaraka za kihistoria</td><td>Juu (machungwa)</td></tr><tr><td>Paradoksi ya Kibinafsi</td><td>Mtu anayerudi nyuma anakutana na yeye mwenyewe wa zamani katika zamani, na mwingiliano wa uwepo wa mtu mmoja wa kibinafsi unaosababisha mkanganyiko wa sababu-na-matokeo wa fahari ya kibinafsi</td><td>Mtu anayerudi nyuma anakutana na kuzungumza na yeye mwenyewe aliyejikita katika zamani, anabadilisha uchaguzi wa maisha wa yeye mwenyewe aliyejikita, na kwa hivyo anabadilisha kumbukumbu na utu wa mtu anayerudi nyuma mwenyewe</td><td>Juu (machungwa)</td></tr><tr><td>Paradoksi ya Tukio</td><td>Tabia ya mtu anayerudi nyuma inabadilisha matokeo ya tukio muhimu la kihistoria, na kusababisha mnyororo wote wa sababu-na-matokeo wa historia inayofuata kuhitaji kujengwa tena</td><td>Mtu anayerudi nyuma anazuia mapigano muhimu katika zamani, na kusababisha historia ya karne kadhaa inayofuata kubadilika kabisa</td><td>Juu sana (nyekundu)</td></tr></tbody></table><p>Bado zaidi ya aina nne kuu hapo juu, kuna paradoksi za mchanganyiko, yaani paradoksi tata zenye sifa za aina zaidi ya moja za paradoksi kwa wakati mmoja. Ugumu wa kuzuia na kurekebisha paradoksi za mchanganyiko ni mkubwa zaidi kuliko wa paradoksi za aina moja, na inahitaji majibu ya dharura ya kiwango cha juu zaidi.</p><h2 id="_3-mfumo-wa-kuzuia-kabla" tabindex="-1">3. Mfumo wa Kuzuia Kabla <a class="header-anchor" href="#_3-mfumo-wa-kuzuia-kabla" aria-label="Permalink to &quot;3. Mfumo wa Kuzuia Kabla&quot;">​</a></h2><p>Mkakati wa kwanza wa kuzuia paradoksi ya wakati ni &quot;kuzua kabla&quot;, yaani kuondoa uwezekano wa kutokea kwa paradoksi kupitia mbinu za kisheria na kiufundi kabla ya operesheni ya kurudi nyuma kwa wakati kuanza. Mfumo wa kuzuia kabla unajumuisha vifungu vya msingi vifuatavyo:</p><h3 id="_3-1-tathmini-ya-sababu-na-matokeo-kabla-ya-kurudi-nyuma" tabindex="-1">3.1 Tathmini ya Sababu-na-matokeo Kabla ya Kurudi Nyuma <a class="header-anchor" href="#_3-1-tathmini-ya-sababu-na-matokeo-kabla-ya-kurudi-nyuma" aria-label="Permalink to &quot;3.1 Tathmini ya Sababu-na-matokeo Kabla ya Kurudi Nyuma&quot;">​</a></h3><p>Operesheni yoyote ya kurudi nyuma kwa wakati kabla ya idhini, lazima ipitie tathmini ya sababu-na-matokeo kabla ya kurudi nyuma na timu ya &quot;wataalamu wa uchambuzi wa sababu-na-matokeo&quot; wenye uzoefu. Maudhui ya tathmini yanajumuisha: msongamano wa mnyororo wa sababu-na-matokeo wa kipindi cha wakati cha lengwa la kurudi nyuma, nafasi na unyeti wa nodi muhimu za kihistoria, kiwango cha uhusiano wa sababu-na-matokeo kati ya mtu anayerudi nyuma mwenyewe na kipindi cha wakati cha lengwa, na upeo wa uotofu wa sababu-na-matokeo ambao tabia iliyopangwa ya kuingilia inaweza kusababisha. Matokeo ya tathmini yanaonyeshwa kwa &quot;fahirisi ya hatari ya paradoksi&quot;; ombi la kurudi nyuma lenye fahirisi zaidi ya 0.1 litakataliwa, na lenye fahirisi kati ya 0.01 na 0.1 litaruhusiwa tu baada ya kuongeza hatua za kuzuia za ziada.</p><h3 id="_3-2-kutengwa-kwa-sababu-na-matokeo-kwa-mtu-anayerudi-nyuma" tabindex="-1">3.2 Kutengwa kwa Sababu-na-matokeo kwa Mtu anayerudi Nyuma <a class="header-anchor" href="#_3-2-kutengwa-kwa-sababu-na-matokeo-kwa-mtu-anayerudi-nyuma" aria-label="Permalink to &quot;3.2 Kutengwa kwa Sababu-na-matokeo kwa Mtu anayerudi Nyuma&quot;">​</a></h3><p>Ili kuzuia kutokea kwa paradoksi ya kuua babu na paradoksi ya kibinafsi, mtu anayerudi nyuma lazima apitie &quot;mchakato wa kutengwa kwa sababu-na-matokeo&quot; kabla ya kuingia katika kipindi cha wakati cha lengwa. Kiini cha kutengwa kwa sababu-na-matokeo ni kupitia operesheni ya sheria ya nanga, &quot;kutoa&quot; kwa muda alama za sababu-na-matokeo za mtu anayerudi nyuma kutoka kwa mnyororo wa sababu-na-matokeo wa ndege ya mwenyewe, na kufanya uwepo wa mtu anayerudi nyuma katika kipindi cha wakati cha lengwa usiunganishi moja kwa moja na mstari wake wa zamani wa sababu-na-matokeo. Baada ya kutengwa kwa sababu-na-matokeo, hata kama mtu anayerudi nyuma anakutana na babu yake mwenyewe au yeye mwenyewe wa zamani katika zamani, hatachochea moja kwa moja paradoksi ya kuua babu au paradoksi ya kibinafsi — kwa sababu uwepo wa mtu anayerudi nyuma tayari umeweka uhuru kwa muda kutoka kwa mnyororo wa asili wa sababu-na-matokeo.</p><p>Muda wa uhalali wa kutengwa kwa sababu-na-matokeo unafanana na muda wa kurudi nyuma, na baada ya kurudi nyuma kumalizika, alama za sababu-na-matokeo za mtu anayerudi nyuma zitaunganishwa tena na mnyororo wa asili wa sababu-na-matokeo. Wakati wa kuunganisha tena, inahitajika kufanya &quot;uhakikisho wa kuendelea kwa sababu-na-matokeo&quot;, na kuhakikisha kuwa uzoefu wa wakati wa kurudi nyuma na kumbukumbu za asili za mtu anayerudi nyuma zinaweza kuunganishwa bila mapungufu.</p><h3 id="_3-3-mfumo-wa-orodha-nyeupe-ya-tabia-ya-kuingilia" tabindex="-1">3.3 Mfumo wa Orodha Nyeupe ya Tabia ya Kuingilia <a class="header-anchor" href="#_3-3-mfumo-wa-orodha-nyeupe-ya-tabia-ya-kuingilia" aria-label="Permalink to &quot;3.3 Mfumo wa Orodha Nyeupe ya Tabia ya Kuingilia&quot;">​</a></h3><p>Tabia za kuingilia katika kurudi nyuma kwa wakati zinafanya &quot;mfumo wa orodha nyeupe&quot; mkali — tu tabia za kuingilia zilizoidhinishwa mapema na kuwekwa kwenye orodha nyeupe ndizo zinaruhusiwa kutekelezwa, na tabia yoyote ya kuingilia nje ya orodha nyeupe inakatazwa kwa mkali. Uundaji wa orodha nyeupe unategemea matokeo ya tathmini ya sababu-na-matokeo kabla ya kurudi nyuma, na unajumuisha tu tabia hizo za kuingilia zenye uotofu mdogo sana wa sababu-na-matokeo na hatari ndogo sana ya paradoksi.</p><p>Mifano ya kawaida ya tabia za kuingilia za orodha nyeupe inajumuisha: kuweka taarifa moja kwenye kona ambayo haitazungumziwa na watu, kufanya mazungumzo mafupi mara moja na mtu ambaye sio mtu muhimu na ambayo haitaathiri njia yake ya maisha, au kufanya mabadiliko madogo sana ya wakati (yasiyozidi sekunde chache) kwa tukio ambalo linakaribia kutokea kwa asili. Tabia yoyote ya kuingilia ambayo inaweza kubadilisha hatima ya mtu muhimu, matokeo ya tukio muhimu, au mwelekeo wa ukuaji wa ustaarabu, haiwezi kuwekwa kwenye orodha nyeupe kwa njia yoyote.</p><h2 id="_4-ufuatiliaji-wa-wakati-wa-operesheni-na-majibu-ya-dharura" tabindex="-1">4. Ufuatiliaji wa Wakati wa Operesheni na Majibu ya Dharura <a class="header-anchor" href="#_4-ufuatiliaji-wa-wakati-wa-operesheni-na-majibu-ya-dharura" aria-label="Permalink to &quot;4. Ufuatiliaji wa Wakati wa Operesheni na Majibu ya Dharura&quot;">​</a></h2><p>Hata kama kuna kuzuia kabla mkali, bado kunaweza kutokea hali zisizotarajiwa wakati wa mchakato wa kurudi nyuma zinazosababisha kuongezeka kwa hatari ya paradoksi. Kwa hivyo, ufuatiliaji wa wakati wa operesheni na majibu ya dharura ni mstari wa pili wa ulinzi wa mfumo wa kuzuia.</p><h3 id="_4-1-ufuatiliaji-wa-sababu-na-matokeo-wa-wakati-wa-halisi" tabindex="-1">4.1 Ufuatiliaji wa Sababu-na-matokeo wa Wakati wa Halisi <a class="header-anchor" href="#_4-1-ufuatiliaji-wa-sababu-na-matokeo-wa-wakati-wa-halisi" aria-label="Permalink to &quot;4.1 Ufuatiliaji wa Sababu-na-matokeo wa Wakati wa Halisi&quot;">​</a></h3><p>Wakati wa operesheni ya kurudi nyuma inayoendelea, mtandao wa nanga unafanya ufuatiliaji wa wakati wa halisi wa hali ya mnyororo wa sababu-na-matokeo wa kipindi cha wakati cha lengwa. Viashiria vya ufuatiliaji vinajumuisha: kiwango cha mabadiliko ya msongamano wa mnyororo wa sababu-na-matokeo, uthabiti wa nodi muhimu, ishara za utangulizi wa paradoksi (mabadiliko yasiyo ya kawaida ya nishati ya sababu-na-matokeo). Data za ufuatiliaji zinasasishwa kila milisekunde, na zinachambuliwa kiotomatiki na &quot;AI ya ufuatiliaji wa sababu-na-matokeo&quot;, na mara tu inapogunduliwa kosa, onyo litatolewa mara moja.</p><h3 id="_4-2-majibu-ya-dharura-ya-viwango-vitatu" tabindex="-1">4.2 Majibu ya Dharura ya Viwango Vitatu <a class="header-anchor" href="#_4-2-majibu-ya-dharura-ya-viwango-vitatu" aria-label="Permalink to &quot;4.2 Majibu ya Dharura ya Viwango Vitatu&quot;">​</a></h3><p>Kulingana na ukubwa wa hatari ya paradoksi, majibu ya dharura yamegawanywa katika viwango vitatu:</p><ul><li><p><strong>Majibu ya kiwango cha tatu (kiwango cha onyo)</strong>: Ufuatiliaji umegundua kuwa kuna kosa dogo katika mnyororo wa sababu-na-matokeo, na fahirisi ya hatari ya paradoksi imepanda juu ya 0.01 lakini chini ya 0.05. Hatua za majibu: kusitisha tabia ya sasa ya kuingilia, kumrudisha mtu anayerudi nyuma katika hali ya ufuatiliaji safi, timu ya wataalamu wa uchambuzi wa sababu-na-matokeo inachambua na kuthamini kosa, na operesheni inaweza kuendelea tu baada ya usalama kuthibitishwa.</p></li><li><p><strong>Majibu ya kiwango cha pili (kiwango cha tahadhari)</strong>: Kosa la mnyororo wa sababu-na-matokeo limeongezeka, fahirisi ya hatari ya paradoksi imepanda juu ya 0.05 lakini chini ya 0.1, au ishara za utangulizi za paradoksi zimeonekana. Hatua za majibu: kumaliza mara moja tabia zote za kuingilia, kuanzisha mchakato wa kurudi nyuma kwa dharura kwa mtu anayerudi nyuma, wakati huo huo mtandao wa nanga unafanya &quot;kufungwa kwa sababu-na-matokeo&quot; kwenye mnyororo wa sababu-na-matokeo wa kipindi cha wakati cha lengwa — kufunga kwa muda hali ya mnyororo wa sababu-na-matokeo, na kuzuia kosa kuenea zaidi.</p></li><li><p><strong>Majibu ya kiwango cha kwanza (kiwango cha msongo)</strong>: Paradoksi tayari imetokea kwa kweli, au fahirisi ya hatari ya paradoksi imezidi 0.1. Hatua za majibu: kuanzisha mara moja majibu ya dharura ya kiwango cha juu zaidi, ikiongozwa moja kwa moja na Kamati ya Sheria za Wakati, kutumia nishati zote za nanga zinazopatikana kufanya operesheni ya &quot;urekebishaji wa sababu-na-matokeo&quot;, wakati huo huo kuandaa kuanzisha mchakato wa &quot;kutengwa kwa mstari wa wakati&quot; — kutenga sehemu ya mstari wa wakati iliyoathiriwa na paradoksi kutoka kwa mstari wa kuu wa wakati, na kuunda mzunguko wa wakati uliofungwa na uhuru, ili kuzuia athari za paradoksi kuenea kwa sehemu nyingine za mstari wa kuu wa wakati.</p></li></ul><h2 id="_5-urekebishaji-wa-sababu-na-matokeo-baada-ya-wakati-na-ukaguzi" tabindex="-1">5. Urekebishaji wa Sababu-na-matokeo baada ya Wakati na Ukaguzi <a class="header-anchor" href="#_5-urekebishaji-wa-sababu-na-matokeo-baada-ya-wakati-na-ukaguzi" aria-label="Permalink to &quot;5. Urekebishaji wa Sababu-na-matokeo baada ya Wakati na Ukaguzi&quot;">​</a></h2><p>Ikiwa paradoksi tayari imetokea, urekebishaji wa sababu-na-matokeo baada ya wakati ni njia ya mwisho ya uokoaji. Njia ya msingi ya urekebishaji wa sababu-na-matokeo ni &quot;njia ya sindano ya nishati ya sababu-na-matokeo&quot; — kupitia mtandao wa nanga, kuingiza nishati ya fidia iliyohesabiwa kwa usahihi katika mnyororo ulioharibika wa sababu-na-matokeo, kufyonza mgongano wa sababu-na-matokeo uliosababishwa na paradoksi, na kufanya mnyororo wa sababu-na-matokeo urudi katika hali thabiti. Mchakato wa urekebishaji unahitaji usahihi wa juu sana, na uotofu wa nishati inayoingizwa haupaswi kuzidi 10 kwa nguvu -6 ya nishati ya lengwa, vinginevyo inaweza kusababisha paradoksi ya pili.</p><p>Kwa paradoksi ambazo tayari zimesababisha matawi ya mstari wa wakati, njia ya urekebishaji ni &quot;kuunganisha mstari wa wakati&quot; — kupitia operesheni ya nanga, kuunganisha tena mstari wa wakati ulio na matawi na mstari wa kuu wa wakati. Wakati wa mchakato wa kuunganisha, matukio tofauti katika mstari wa wakati ulio na matawi yanahitajika &quot;kufunikwa kwa sababu-na-matokeo&quot;, yaani kutumia matukio asili ya mstari wa kuu wa wakati kufunika matukio ya matawi, na mwishowe kubaki tu na mstari mmoja wa wakati uliounganishwa.</p><p>Baada ya operesheni zote za kurudi nyuma kwa wakati kumalizika, zote lazima zipitie &quot;ukaguzi wa baada ya operesheni ya wakati&quot;. Ukaguzi unawajibika na Kamati ya Ukaguzi wa Sheria za Wakati, na maudhui yake yanajumuisha: operesheni ya kurudi nyuma imefanywa kwa mkati kulingana na mpango wa idhini au la, kuna tabia ya kuingilia nje ya orodha nyeupe au la, data za ufuatiliaji za sababu-na-matokeo zimekamili au la, kulikuwa na hatari ya paradoksi au la na utekelezaji wake uliofaa au la. Ripoti ya ukaguzi inahifadhiwa kwa kudumu, kama rujia muhimu kwa idhini za kurudi nyuma za baadaye.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Mfumo wa kuzuia na kudhibiti paradoksi ya wakati ni uhandisi wa usalama ulio sahihi na tata zaidi wa Hengyuanzhou katika uwanja wa sheria za wakati. Kwa kuzuia kabla kama msingi, ufuatiliaji wa wakati wa operesheni kama kizuizi, na urekebishaji wa baada ya wakati kama dhamana ya mwisho, limeunda mfumo wa kuzuia wa mnyororo mzima wa &quot;kuzua—ufuatiliaji—majibu—urekebishaji—ukaguzi&quot;. Uwepo wa mfumo huu unafanya kurudi nyuma kwa wakati, uwezo huu wa sheria wenye nguvu na hatari, uweze kutumika kwa usalama katika kichunguzi na utafiti, badala ya kuwa kisanduku cha Pandora kinachoharibu utaratibu wa sababu-na-matokeo wa ulimwengu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>82-Kanuni za Msingi za Kurudi Nyuma kwa Wakati</li><li>83-Kanuni ya Kuzingatia Kabla Kisha Kuingilia kwa Mdogo</li><li>27-Kalibrashoni na Matengenezo ya Nanga</li></ul>',35)])])}const b=i(t,[["render",o]]);export{y as __pageData,b as default};
